  revoke_anon text[] := ARRAY['accept_vehicle_suggestion', 'activate_auction_listing', 'add_activity_feed_item', 'add_chat_message', 'add_dynamic_vehicle_field', 'add_photo_comment', 'admin_approve_ownership_verification', 'admin_reject_ownership_verification', 'allocate_credits_to_vehicle', 'approve_external_identity_claim', 'approve_ownership_verification', 'approve_pending_assignment', 'attribute_image_session', 'award_achievement', 'backfill_user_profile_stats', 'backfill_work_sessions_from_photos', 'bulk_add_to_image_set', 'bulk_link_photos_to_vehicle', 'confirm_work_session', 'convert_personal_album_to_vehicle', 'create_notification', 'create_user_request', 'deduct_cash_from_user', 'derive_work_sessions', 'ensure_field_evidence', 'finalize_work_session', 'generate_invite_code', 'generate_spending_analytics', 'increment_device_image_count', 'increment_document_stat', 'join_stream', 'log_contribution', 'log_pii_access', 'log_quick_action', 'log_usage_metric', 'log_vehicle_edit', 'mark_all_notifications_read', 'mark_notification_read', 'merge_duplicate_vehicles', 'purchase_auction_premium_timing', 'purchase_stream_action_pack', 'record_interaction', 'record_owner_contribution', 'reject_pending_assignment', 'reject_vehicle_suggestion', 'relink_testimony', 'reorder_image_set', 'request_account_deletion', 'request_external_identity_claim', 'revoke_garage_membership', 'send_content_action', 'send_stream_action', 'set_analysis_credential', 'set_analysis_method', 'set_image_priority', 'set_primary_document', 'set_vehicle_build_image', 'set_vehicle_price_baseline', 'supersede_observation', 'sync_local_vision_tags', 'unmerge_vehicle', 'update_follow_roi_tracking', 'update_organization_profile_stats', 'update_user_profile_stats', 'update_vehicle_relationship', 'verify_shop'];
BEGIN
  SELECT count(*) FILTER (WHERE has_function_privilege('anon', p.oid, 'EXECUTE')),
         count(*) FILTER (WHERE has_function_privilege('authenticated', p.oid, 'EXECUTE'))
    INTO before_anon, before_auth
    FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace
   WHERE ns.nspname = 'public' AND p.prokind IN ('f','p') AND p.prorettype <> 'trigger'::regtype AND p.proname = ANY (writers);

  -- (c) not called by the web app or the capture app: service_role / postgres only
  FOR r IN SELECT p.oid::regprocedure AS sig
             FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace
            WHERE ns.nspname = 'public' AND p.prokind IN ('f','p') AND p.prorettype <> 'trigger'::regtype AND p.proname = ANY (revoke_all)
  LOOP
    EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC, anon, authenticated', r.sig);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role', r.sig);
    n_all := n_all + 1;
  END LOOP;

  -- (b)/(ios) signed-in callers only
  FOR r IN SELECT p.oid::regprocedure AS sig
             FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace
            WHERE ns.nspname = 'public' AND p.prokind IN ('f','p') AND p.prorettype <> 'trigger'::regtype AND p.proname = ANY (revoke_anon)
  LOOP
    EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC, anon', r.sig);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated, service_role', r.sig);
    n_anon := n_anon + 1;
  END LOOP;

  SELECT count(*) FILTER (WHERE has_function_privilege('anon', p.oid, 'EXECUTE')),
         count(*) FILTER (WHERE has_function_privilege('authenticated', p.oid, 'EXECUTE'))
    INTO after_anon, after_auth
    FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace
   WHERE ns.nspname = 'public' AND p.prokind IN ('f','p') AND p.prorettype <> 'trigger'::regtype AND p.proname = ANY (writers);

  RAISE NOTICE 'P0.4: % signatures closed to anon+authenticated, % closed to anon; writing signatures executable by anon % -> %, by authenticated % -> %',
    n_all, n_anon, before_anon, after_anon, before_auth, after_auth;
END
